#!/usr/bin/env python3
"""Rebuild docs/concept-asset-credits.md from every storefront/src/k/<id>/assets.json."""
import json, os, glob
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
lines = ['# Concept photography credits', '', 'Generated by `scripts/concept-assets/credits.py`. Every photograph used by the redesigned concept mini-sites, with its source page and licence. CC0 / public-domain files need no attribution; authors are credited on each concept page anyway. Candidates were found with the public Openverse API (api.openverse.org) and downloaded from the source host; the local files in `storefront/public/assets/k/` are resized/cropped WebP derivatives made by `scripts/concept-assets/process.py`.', '', '| File | Title | Author | Licence | Source |', '|---|---|---|---|---|']
for f in sorted(glob.glob(os.path.join(ROOT, 'storefront', 'src', 'k', '*', 'assets.json'))):
    for k, v in sorted(json.load(open(f)).items()):
        lines.append(f"| `{k}` | {v['title'].replace('|', '/')[:90]} | {v['creator'].replace('|', '/')} | {v['license']} | [{v['sourceName']}]({v['page']}) |")
open(os.path.join(ROOT, 'docs', 'concept-asset-credits.md'), 'w').write('\n'.join(lines) + '\n')
print(len(lines) - 6, 'credits')
